+	$E_\ast\operatorname{Unif}(A)=\operatorname{Unif}(B)$.
+\end{lemma}
+\begin{proof}
+	\leanok
+	\uses{lem:uniform-map-equal-fibers}
+	Every fiber of an equivalence has cardinality one, so the result follows from
+	Lemma~\ref{lem:uniform-map-equal-fibers}.
+\end{proof}
