550	\begin{corollary}[Qubit form of the soundness of the Pauli basis test]\label{cor:pauli-binary}
551		\lean{MIPStarRE.QPBT.pauli_soundness_qubit}
552		\leanok
553		\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:tensor-product-value, def:EPR, def:povm-distance, def:binary-representation}
554		There exists a function
555		\[
556			\delta_{\mathrm{qld}}(\eps, m, d, q) = a\,(md)^a \bigl( \eps^b + q^{-b} + 2^{-bmd} \bigr)
557		\]
558		% The paper's displayed function here writes the argument order (eps, q, m, d); the
559		% formula is the same, and its own item 1 reverts to (eps, m, d, q). See the remark below.
560		for universal constants $a \ge 1$ and $0 < b < 1$ such that the following holds. For all admissible parameter tuples $\mathsf{qldparams} = (q,m,d)$ and for all strategies $\mathcal S = (\ket\psi, A, B)$ for the game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ that succeed with probability at least $1 - \eps$, there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\ket\psi \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''} \cong (\C^2)^{\ot M \log q}$ with $M = 2^m$, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A'} \ot \hilb_{\mathrm B'}$, such that:
561		\begin{enumerate}
562			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket\psi - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_2}^{\ot M \log q} \bigr\| \le \delta_{\mathrm{qld}}(\eps, m, d, q)$;
563			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$, for $W \in \{X, Z\}$,
564			\begin{align*}
565				\tilde A^{(\mathsf{Pauli},W)}_u \ot I_{\mathrm{B'B''}} &\approx_{\delta_{\mathrm{qld}}} (\sigma^W_u)_{\mathrm A''} \ot I_{\mathrm{A'B'B''}}\;,\\
566				I_{\mathrm{A'A''}} \ot \tilde B^{(\mathsf{Pauli},W)}_u &\approx_{\delta_{\mathrm{qld}}} I_{\mathrm{A'A''B'}} \ot (\sigma^W_u)_{\mathrm B''}\;,
567			\end{align*}
568			where the $\approx_{\delta_{\mathrm{qld}}}$ statements hold with respect to the state $\ket{\mathrm{aux}}_{\mathrm{A'B'}} \ot \ket{\mathrm{EPR}_2}^{\ot M \log q}_{\mathrm{A''B''}}$ and the answer summation is over $u \in \F_q^M$. Here $\sigma^W_u$ denotes the tensor product of single-qubit Pauli measurements
569			\[
570				\bigotimes_{i=1}^{M} \bigotimes_{j=1}^{\log q} \sigma^W_{u_{ij}}\;,
571			\]
572			where $\kappa(u_i) = (u_{ij})_{1 \le j \le \log q}$ under the bijection $\kappa\colon \F_q \to \F_2^{\log q}$ of Chapter~\ref{chap:qpbt-algebra}.
573		\end{enumerate}
574	\end{corollary}
575	\begin{proof}
576		\uses{thm:pauli, lem:pauli-binary}
577		By Lemma~\ref{lem:pauli-binary}, since $q$ is a power of $2$ there are local isometries that map $\ket{\mathrm{EPR}_q}^{\ot M}$ to $\ket{\mathrm{EPR}_2}^{\ot M \log q}$ and map the generalized Pauli measurements $\tau^W_u$ to the qubit tensor products $\bigotimes_{i=1}^M \bigotimes_{j=1}^{\log q} \sigma^W_{u_{ij}}$, where $\kappa(u_i) = (u_{i1},\ldots,u_{i \log q})$. Composing these isometries with those produced by Theorem~\ref{thm:pauli} gives the statement.
578	\end{proof}
