430	\begin{lemma}[Conditionally linear Pauli question maps]\label{lem:pauli-question-cl-components}
431		\lean{MIPStarRE.QPBT.isCondLinear_pauliCL}
432		\uses{def:pauli-question-distribution, def:typed-cl-functions}
433		For every Pauli question type $t \in \mathcal T^{\mathrm{pauli}}$, the map $L_t$ of Definition~\ref{def:pauli-question-distribution} is conditionally linear. Its levels are $1$ for the point maps, $2$ for the axis-parallel line maps, $3$ for the diagonal line maps, $1$ for the shared projection maps, and $0$ for the Pauli maps.
434	\end{lemma}
435	\begin{proof}
436		\uses{lem:ld-point-level, lem:ld-aline-level, lem:ld-dline-level}
437		Transport the point, axis-parallel line, and diagonal line representations to the selected basis register. The shared projection onto the point and auxiliary registers is linear, while the Pauli maps are zero. These representations have levels $1$, $2$, $3$, $1$, and $0$, respectively.
438	\end{proof}
