440	\begin{lemma}[Common level of the Pauli question maps]\label{lem:pauli-question-cl-family-obligation}
441		\lean{MIPStarRE.QPBT.isTypedCondLinearFamily_pauliCL}
442		\uses{def:pauli-question-distribution, def:typed-cl-functions}
443		For every Pauli question type $t \in \mathcal T^{\mathrm{pauli}}$, the map $L_t$ of Definition~\ref{def:pauli-question-distribution} is a $3$-level CL function. Thus $L = \{L_t\}_{t \in \mathcal T^{\mathrm{pauli}}}$ is a finite typed family of $3$-level CL functions.
444	\end{lemma}
445	\begin{proof}
446		\uses{lem:pauli-question-cl-components, lem:cl-level-mono}
447		The component maps have levels at most $3$ by Lemma~\ref{lem:pauli-question-cl-components}. Lemma~\ref{lem:cl-level-mono} raises each representation to the common level $3$.
448	\end{proof}
