  94	`references/qpbt-paper/05_conditionally_linear_functions.tex:35-57`.
  95	-/
  96	def IsCondLinearOn (K : Type*) [Field K] {ι : Type*} [Fintype ι]
  97	    [DecidableEq ι] (S : Finset ι) (ell : ℕ)
  98	    (L : (ι → K) → (ι → K)) : Prop :=
  99	  ∃ t : CondLinearTerm K (ι := ι) ell,
 100	    CondLinearTerm.supportedOn t S ∧ CondLinearTerm.eval t = L
 101	
 102	/--
 103	`IsCondLinear` abbreviates the full-coordinate predicate.  Blueprint
 104	`def:cl-func`, `blueprint/src/chapter/ch12_qpbt_games.tex:1185-1195`; paper
 105	`references/qpbt-paper/05_conditionally_linear_functions.tex:35-57`.
 106	-/
 107	def IsCondLinear (ell : ℕ) (L : (ι → K) → (ι → K)) : Prop :=
 108	  IsCondLinearOn K Finset.univ ell L
