 110	/-- The zero conditionally linear function at every level, used to extend the
 111	family `R u` from the image `L(U)` to all indices in the concatenation
 112	construction of `lem:cl-concat`. -/
 113	private def CondLinearTerm.zeroOfLevel {K ι : Type*} [Field K]
 114	    [Fintype ι] [DecidableEq ι] : (ell : ℕ) → CondLinearTerm K (ι := ι) ell
 115	  | 0 => .zero
 116	  | ell + 1 => .succ ∅ 0 (by simp) (fun _ => zeroOfLevel ell)
 117	
 118	@[simp]
 119	private theorem CondLinearTerm.eval_zeroOfLevel {K ι : Type*} [Field K]
 120	    [Fintype ι] [DecidableEq ι] (ell : ℕ) (x : ι → K) :
 121	    CondLinearTerm.eval (CondLinearTerm.zeroOfLevel (K := K) (ι := ι) ell) x = 0 := by
 122	  induction ell with
 123	  | zero => rfl
 124	  | succ ell ih =>
 125	      simp [CondLinearTerm.zeroOfLevel, CondLinearTerm.eval, ih]
