 127	private theorem CondLinearTerm.zeroOfLevel_supportedOn {K ι : Type*} [Field K]
 128	    [Fintype ι] [DecidableEq ι] (ell : ℕ) (S : Finset ι) :
 129	    CondLinearTerm.supportedOn
 130	      (CondLinearTerm.zeroOfLevel (K := K) (ι := ι) ell) S := by
 131	  induction ell generalizing S with
 132	  | zero => trivial
 133	  | succ ell ih =>
 134	      exact ⟨by simp, fun _ => ih _⟩
