 136	/-- Extending the support set preserves the support invariant. -/
 137	private theorem CondLinearTerm.supportedOn_mono {K ι : Type*} [Field K]
 138	    [Fintype ι] [DecidableEq ι] {ell : ℕ}
 139	    {t : CondLinearTerm K (ι := ι) ell} {S T : Finset ι}
 140	    (ht : CondLinearTerm.supportedOn t S) (hST : S ⊆ T) :
 141	    CondLinearTerm.supportedOn t T := by
 142	  induction t generalizing S T with
 143	  | zero => trivial
 144	  | @succ ell S₁ L₁ hSupport rest ih =>
 145	      rcases ht with ⟨hS₁, hrest⟩
 146	      refine ⟨hS₁.trans hST, fun y => ih y (hrest y) ?_⟩
 147	      exact Finset.sdiff_subset_sdiff hST (fun _ h => h)
