 149	/-- Lift a linear map to the left summand of a direct sum of registers. -/
 150	private def condLinearLiftLeft {K ιU ιV : Type*} [Field K]
 151	    (L : (ιU → K) →ₗ[K] (ιU → K)) :
 152	    (ιU ⊕ ιV → K) →ₗ[K] (ιU ⊕ ιV → K) where
 153	  toFun x := Sum.elim (L (fun i => x (.inl i))) 0
 154	  map_add' x y := by
 155	    ext i
 156	    cases i with
 157	    | inl i => exact congrFun (L.map_add _ _) i
 158	    | inr i => simp
 159	  map_smul' c x := by
 160	    ext i
 161	    cases i with
 162	    | inl i => exact congrFun (L.map_smul c _) i
 163	    | inr i => simp
 164	
 165	/-- Lift a linear map to the right summand of a direct sum of registers. -/
 166	private def condLinearLiftRight {K ιU ιV : Type*} [Field K]
 167	    (L : (ιV → K) →ₗ[K] (ιV → K)) :
 168	    (ιU ⊕ ιV → K) →ₗ[K] (ιU ⊕ ιV → K) where
 169	  toFun x := Sum.elim 0 (L (fun i => x (.inr i)))
 170	  map_add' x y := by
 171	    ext i
 172	    cases i with
 173	    | inl i => simp
 174	    | inr i => exact congrFun (L.map_add _ _) i
 175	  map_smul' c x := by
 176	    ext i
 177	    cases i with
 178	    | inl i => simp
 179	    | inr i => exact congrFun (L.map_smul c _) i
 180	
 181	/-- Lift a representation of a conditionally linear function to the right
 182	summand of a direct sum of registers. -/
 183	private def CondLinearTerm.liftRight {K ιU ιV : Type*} [Field K]
 184	    [Fintype ιU] [DecidableEq ιU] [Fintype ιV] [DecidableEq ιV] :
 185	    {ell : ℕ} → CondLinearTerm K (ι := ιV) ell →
 186	      CondLinearTerm K (ι := ιU ⊕ ιV) ell
 187	  | _, .zero => .zero
 188	  | _, .succ S₁ L₁ hSupport rest =>
 189	      .succ (S₁.map Function.Embedding.inr) (condLinearLiftRight L₁)
 190	        (by
 191	          intro x i hi
 192	          cases i with
 193	          | inl i => rfl
 194	          | inr i =>
 195	              apply hSupport
 196	              simpa using hi)
 197	        (fun y => liftRight (rest (fun i => y (.inr i))))
 198	
 199	@[simp]
 200	private theorem CondLinearTerm.eval_liftRight {K ιU ιV : Type*} [Field K]
 201	    [Fintype ιU] [DecidableEq ιU] [Fintype ιV] [DecidableEq ιV]
 202	    {ell : ℕ} (t : CondLinearTerm K (ι := ιV) ell) (x : ιU ⊕ ιV → K) :
 203	    CondLinearTerm.eval (CondLinearTerm.liftRight (ιU := ιU) t) x =
 204	      Sum.elim (0 : ιU → K) (CondLinearTerm.eval t (fun i => x (.inr i))) := by
 205	  induction t with
 206	  | zero =>
 207	      simp [CondLinearTerm.liftRight, CondLinearTerm.eval]
 208	  | @succ ell S₁ L₁ hSupport rest ih =>
 209	      ext i
 210	      cases i <;>
 211	        simp [CondLinearTerm.liftRight, CondLinearTerm.eval, condLinearLiftRight,
 212	          coordinateRestriction, ih]; rfl
 213	
 214	private theorem CondLinearTerm.liftRight_supportedOn {K ιU ιV : Type*}
 215	    [Field K] [Fintype ιU] [DecidableEq ιU] [Fintype ιV] [DecidableEq ιV]
 216	    {ell : ℕ} {t : CondLinearTerm K (ι := ιV) ell} {S : Finset ιV}
 217	    (ht : CondLinearTerm.supportedOn t S) :
 218	    CondLinearTerm.supportedOn (CondLinearTerm.liftRight (ιU := ιU) t)
 219	      (S.map Function.Embedding.inr) := by
 220	  induction t generalizing S with
 221	  | zero => trivial
 222	  | @succ ell S₁ L₁ hSupport rest ih =>
 223	      rcases ht with ⟨hS₁, hrest⟩
 224	      refine ⟨Finset.map_subset_map.mpr hS₁, fun y => ?_⟩
 225	      have hsets :
 226	          (S \ S₁).map (Function.Embedding.inr : ιV ↪ ιU ⊕ ιV) =
 227	            S.map Function.Embedding.inr \ S₁.map Function.Embedding.inr := by
 228	        ext i
 229	        cases i <;> simp
 230	      rw [← hsets]
 231	      exact ih (fun i => y (.inr i)) (hrest (fun i => y (.inr i)))
