 233	/-- Concatenate a family of conditionally linear representations on the right
 234	register with a conditionally linear representation on the left register, while
 235	recording the prefix accumulated by the preceding left levels. -/
 236	private def CondLinearTerm.concat {K ιU ιV : Type*} [Field K]
 237	    [Fintype ιU] [DecidableEq ιU] [Fintype ιV] [DecidableEq ιV]
 238	    {ell : ℕ} (rTerm : (ιU → K) → CondLinearTerm K (ι := ιV) ell)
 239	    (acc : ιU → K) :
 240	    {k : ℕ} → CondLinearTerm K (ι := ιU) k →
 241	      CondLinearTerm K (ι := ιU ⊕ ιV) (ell + k)
 242	  | _, .zero => CondLinearTerm.liftRight (rTerm acc)
 243	  | _, .succ S₁ L₁ hSupport rest =>
 244	      .succ (S₁.map Function.Embedding.inl) (condLinearLiftLeft L₁)
 245	        (by
 246	          intro x i hi
 247	          cases i with
 248	          | inl i =>
 249	              apply hSupport
 250	              simpa using hi
 251	          | inr i => rfl)
 252	        (fun y => concat rTerm (acc + fun i => y (.inl i))
 253	          (rest (fun i => y (.inl i))))
 254	
 255	private theorem CondLinearTerm.eval_concat {K ιU ιV : Type*} [Field K]
 256	    [Fintype ιU] [DecidableEq ιU] [Fintype ιV] [DecidableEq ιV]
 257	    {ell k : ℕ} (rTerm : (ιU → K) → CondLinearTerm K (ι := ιV) ell)
 258	    (acc : ιU → K) (t : CondLinearTerm K (ι := ιU) k)
 259	    (x : ιU ⊕ ιV → K) :
 260	    CondLinearTerm.eval (CondLinearTerm.concat rTerm acc t) x =
 261	      Sum.elim (CondLinearTerm.eval t (fun i => x (.inl i)))
 262	        (CondLinearTerm.eval
 263	          (rTerm (acc + CondLinearTerm.eval t (fun i => x (.inl i))))
 264	          (fun i => x (.inr i))) := by
 265	  induction t generalizing acc with
 266	  | zero =>
 267	      simp [CondLinearTerm.concat, CondLinearTerm.eval]
 268	  | @succ k S₁ L₁ hSupport rest ih =>
 269	      ext i
 270	      cases i <;>
 271	        simp [CondLinearTerm.concat, CondLinearTerm.eval, condLinearLiftLeft,
 272	          coordinateRestriction, ih, add_assoc] <;> rfl
 273	
 274	private theorem CondLinearTerm.concat_supportedOn {K ιU ιV : Type*} [Field K]
 275	    [Fintype ιU] [DecidableEq ιU] [Fintype ιV] [DecidableEq ιV]
 276	    {ell k : ℕ} {rTerm : (ιU → K) → CondLinearTerm K (ι := ιV) ell}
 277	    {acc : ιU → K} {t : CondLinearTerm K (ι := ιU) k}
 278	    {SU : Finset ιU} {SV : Finset ιV}
 279	    (ht : CondLinearTerm.supportedOn t SU)
 280	    (hr : ∀ u, CondLinearTerm.supportedOn (rTerm u) SV) :
 281	    CondLinearTerm.supportedOn (CondLinearTerm.concat rTerm acc t)
 282	      (SU.map Function.Embedding.inl ∪ SV.map Function.Embedding.inr) := by
 283	  induction t generalizing acc SU with
 284	  | zero =>
 285	      exact CondLinearTerm.supportedOn_mono
 286	        (CondLinearTerm.liftRight_supportedOn (hr acc)) Finset.subset_union_right
 287	  | @succ k S₁ L₁ hSupport rest ih =>
 288	      rcases ht with ⟨hS₁, hrest⟩
 289	      refine ⟨(Finset.map_subset_map.mpr hS₁).trans Finset.subset_union_left,
 290	        fun y => ?_⟩
 291	      have hrec := ih (fun i => y (.inl i)) (acc := acc + fun i => y (.inl i))
 292	        (hrest (fun i => y (.inl i)))
 293	      have hsets :
 294	          (SU \ S₁).map Function.Embedding.inl ∪ SV.map Function.Embedding.inr =
 295	            (SU.map Function.Embedding.inl ∪ SV.map Function.Embedding.inr) \
 296	              S₁.map Function.Embedding.inl := by
 297	        ext i
 298	        cases i <;> simp
 299	      simpa only [hsets] using hrec
