  30	    [Fintype ι] [DecidableEq ι] {ell : ℕ}
  31	    (t : CondLinearTerm K (ι := ι) ell) : CondLinearTerm K (ι := ι) (ell + 1) :=
  32	  .succ ∅ 0 (by simp) (fun _ => t)
