  34	@[simp]
  35	private theorem CondLinearTerm.eval_raiseLevel {K ι : Type*} [Field K]
  36	    [Fintype ι] [DecidableEq ι] {ell : ℕ}
  37	    (t : CondLinearTerm K (ι := ι) ell) (x : ι → K) :
