  48	/-- Raise a representation of a conditionally linear function by a specified
  49	number of levels, each with zero linear contribution. -/
  50	private def CondLinearTerm.raiseBy {K ι : Type*} [Field K]
  51	    [Fintype ι] [DecidableEq ι] :
  52	    (d : ℕ) → {ell : ℕ} → CondLinearTerm K (ι := ι) ell →
  53	      CondLinearTerm K (ι := ι) (ell + d)
  54	  | 0, _, t => t
  55	  | d + 1, _, t => (raiseBy d t).raiseLevel
