  59	    [Fintype ι] [DecidableEq ι] (d : ℕ) {ell : ℕ}
  60	    (t : CondLinearTerm K (ι := ι) ell) (x : ι → K) :
  61	    CondLinearTerm.eval (CondLinearTerm.raiseBy d t) x = CondLinearTerm.eval t x := by
  62	  induction d with
  63	  | zero => rfl
