  66	private theorem CondLinearTerm.raiseBy_supportedOn {K ι : Type*} [Field K]
  67	    [Fintype ι] [DecidableEq ι] (d : ℕ) {ell : ℕ}
  68	    {t : CondLinearTerm K (ι := ι) ell} {S : Finset ι}
  69	    (ht : CondLinearTerm.supportedOn t S) :
