  75	/-- Conditional linearity is monotone in the number of levels. -/
  76	private theorem IsCondLinearOn.mono_level {K ι : Type*} [Field K]
  77	    [Fintype ι] [DecidableEq ι] {S : Finset ι} {ell k : ℕ}
  78	    {L : (ι → K) → (ι → K)} (hL : IsCondLinearOn K S ell L)
  79	    (h : ell ≤ k) : IsCondLinearOn K S k L := by
  80	  rcases hL with ⟨t, ht, ht_eval⟩
  81	  have hk : ell + (k - ell) = k := Nat.add_sub_of_le h
  82	  rw [← hk]
  83	  exact ⟨CondLinearTerm.raiseBy (k - ell) t,
  84	    CondLinearTerm.raiseBy_supportedOn _ ht,
  85	    funext fun x => by rw [CondLinearTerm.eval_raiseBy, congrFun ht_eval x]⟩
