  87	/-- A conditionally-linear map supported on `S` has values supported on `S`. -/
  88	private theorem IsCondLinearOn.apply_eq_zero_of_not_mem {K ι : Type*} [Field K]
  89	    [Fintype ι] [DecidableEq ι] {S : Finset ι} {ell : ℕ}
  90	    {L : (ι → K) → (ι → K)} (hL : IsCondLinearOn K S ell L)
  91	    (x : ι → K) {a : ι} (ha : a ∉ S) : L x a = 0 := by
  92	  rcases hL with ⟨t, ht, ht_eval⟩
  93	  rw [← congrFun (congrFun ht_eval x) a]
  94	  exact CondLinearTerm.eval_eq_zero_of_not_mem ht x ha
