  96	/-- A conditionally-linear map supported on `S` depends only on the input in
  97	`S`. -/
  98	private theorem IsCondLinearOn.apply_coordinateRestriction {K ι : Type*} [Field K]
  99	    [Fintype ι] [DecidableEq ι] {S : Finset ι} {ell : ℕ}
 100	    {L : (ι → K) → (ι → K)} (hL : IsCondLinearOn K S ell L)
 101	    (x : ι → K) : L (coordinateRestriction S x) = L x := by
 102	  rcases hL with ⟨t, ht, ht_eval⟩
 103	  rw [← congrFun ht_eval, CondLinearTerm.eval_coordinateRestriction ht,
 104	    congrFun ht_eval]
