 106	/-- Prepend a first-level linear contribution, supported on one register, to a
 107	family of residual conditionally linear maps indexed by its value. -/
 108	private theorem IsCondLinearOn.cons {K ι : Type*} [Field K]
 109	    [Fintype ι] [DecidableEq ι] {S S₁ : Finset ι} {ell : ℕ}
 110	    (L₁ : (ι → K) →ₗ[K] (ι → K))
 111	    (hS₁ : S₁ ⊆ S) (hSupport : ∀ x a, a ∉ S₁ → L₁ x a = 0)
 112	    (R : (ι → K) → (ι → K) → (ι → K))
 113	    (hR : ∀ y, IsCondLinearOn K (S \ S₁) ell (R y)) :
 114	    IsCondLinearOn K S (ell + 1) (fun x =>
 115	      L₁ (coordinateRestriction S₁ x) +
 116	        R (L₁ (coordinateRestriction S₁ x)) x) := by
 117	  classical
 118	  choose t ht ht_eval using hR
